import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 11
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        skipinitialspace=False,
        strict=False,
    )

    columns = None
    pending = []
    for record in records:
        # The preamble consists of blank records and single-cell titles.
        if sum(bool(value.strip()) for value in record) >= 2:
            columns = record
            break
        pending.append(record)

    if columns is None:
        if not pending:
            return {"columns": [], "rows": []}
        columns = []
        rows = pending
    else:
        rows = list(records)

    width = max(expected_width, len(columns), max(map(len, rows), default=0))
    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        base = f"column_{position}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
